CREATE TABLE IF NOT EXISTS continental_jurisdictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_code text NOT NULL UNIQUE, country_name text NOT NULL, region_code text, status text NOT NULL DEFAULT 'Framework', legal_framework_version text, data_protection_notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jurisdiction_rights_frameworks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, tenure_category text NOT NULL, community_recognition_model text, consultation_requirement text, consent_requirement text, traditional_authority_role text, benefit_sharing_model text, grievance_model text, disclosure_requirement text, restricted_data_rules text, effective_from timestamptz, effective_until timestamptz, source_reference text, status text NOT NULL DEFAULT 'Draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jurisdiction_transparency_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid NOT NULL REFERENCES continental_jurisdictions(id) ON DELETE CASCADE, subject_type text NOT NULL, public_fields jsonb NOT NULL DEFAULT '[]'::jsonb, restricted_fields jsonb NOT NULL DEFAULT '[]'::jsonb, consent_required boolean NOT NULL DEFAULT false, rule_reason text, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_value_transparency_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, jurisdiction_id uuid REFERENCES continental_jurisdictions(id) ON DELETE SET NULL, community_count integer NOT NULL DEFAULT 0, active_plans integer NOT NULL DEFAULT 0, obligations_open integer NOT NULL DEFAULT 0, milestones_pending integer NOT NULL DEFAULT 0, distributions_recorded integer NOT NULL DEFAULT 0, grievances_open integer NOT NULL DEFAULT 0, disclosure_status text NOT NULL DEFAULT 'Restricted', summary text, generated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_jurisdiction_frameworks ON jurisdiction_rights_frameworks(jurisdiction_id,status);
CREATE INDEX IF NOT EXISTS idx_transparency_rules ON jurisdiction_transparency_rules(jurisdiction_id,status);
CREATE INDEX IF NOT EXISTS idx_value_transparency_asset ON community_value_transparency_snapshots(asset_id,generated_at DESC);